-- =====================================================
-- QUICK VERIFICATION
-- =====================================================
SELECT COUNT(*) AS education_categories_count FROM education_categories;
SELECT COUNT(*) AS education_programs_count FROM education_programs;
SELECT COUNT(*) AS domains_count FROM domains;
SELECT COUNT(*) AS careers_count FROM careers_v2;
SELECT COUNT(*) AS skills_count FROM skills_v2;
SELECT COUNT(*) AS career_skill_requirements_count FROM career_skill_requirements;

-- Example: inspect one career profile
SELECT c.name AS career, s.name AS skill, csr.required_level
FROM careers_v2 c
JOIN career_skill_requirements csr ON csr.career_id = c.id
JOIN skills_v2 s ON s.id = csr.skill_id
WHERE c.name = 'Data Scientist'
ORDER BY csr.required_level DESC, s.name;
